      const text = responseText((await res.json()) as OpenAIResponseBody);
      const level = /\b(high|medium|low)\b/i.exec(text)?.[1]?.toLowerCase() ?? "medium";

      return { level: level as RiskAssessment["level"], reason: text.trim() };
    },
  };
}
